def transform_v2(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Check for horizontal separator (row of all same non-zero)
    sep_row = None
    for i in range(rows):
        val = grid[i][0]
        if val != 0 and all(grid[i][j] == val for j in range(cols)):
            sep_row = i
            break

    # Check for vertical separator (column of all same non-zero)
    sep_col = None
    if sep_row is None:
        for j in range(cols):
            val = grid[0][j]
            if val != 0 and all(grid[i][j] == val for i in range(rows)):
                sep_col = j
                break

    if sep_row is not None:
        # Horizontal separator: compare top and bottom sections by column
        top = grid[:sep_row]
        bottom = grid[sep_row+1:]
        h, w = len(top), len(top[0])
        output = [[0] * w for _ in range(h)]
        for j in range(w):
            for i in range(h):
                if top[i][j] != 0 and bottom[i][j] != 0:
                    output[i][j] = 2
        return output
    else:
        # Vertical separator: compare left and right sections by row
        left = [row[:sep_col] for row in grid]
        right = [row[sep_col+1:] for row in grid]
        h, w = len(left), len(left[0])
        output = [[0] * w for _ in range(h)]
        for i in range(h):
            for j in range(w):
                if left[i][j] != 0 and right[i][j] != 0:
                    output[i][j] = 2
        return output

